 <body>
   <main>
     <section class="intro" aria-labelledby="page-title">
       <p class="eyebrow">Support team</p>
       <h1 id="page-title">How can we help?</h1>
       <p>Send us your details and our support team will get back to you with clear next steps.</p>
     </section>

     <section class="card" aria-labelledby="form-title">
       <div class="card-header">
         <h2 id="form-title">Contact support</h2>
         <p>Fields marked as required must be completed before submitting.</p>
       </div>

       <form id="support-form" novalidate>
         <p class="success-message" id="success-message" role="status">Thanks! Your support request is ready to send.</p>

         <div class="form-field" id="full-name-field">
           <label for="full-name">Full name</label>
           <input
             type="text"
             id="full-name"
             name="fullName"
             autocomplete="name"
             placeholder="Jane Cooper"
             aria-describedby="full-name-error"
             required
           >
           <p class="error-message" id="full-name-error" aria-live="polite"></p>
         </div>

         <div class="form-field" id="email-field">
           <label for="email">Email address</label>
           <input
             type="email"
             id="email"
             name="email"
             autocomplete="email"
             placeholder="jane@example.com"
             aria-describedby="email-error"
             required
           >
           <p class="error-message" id="email-error" aria-live="polite"></p>
         </div>

         <div class="form-field" id="phone-field">
           <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
           <input
             type="tel"
             id="phone"
             name="phone"
             autocomplete="tel"
             placeholder="+1 555 123 4567"
             aria-describedby="phone-help phone-error"
           >
           <p class="helper-text" id="phone-help">Use an international or local format, such as +1 555 123 4567 or (555) 123-4567.</p>
           <p class="error-message" id="phone-error" aria-live="polite"></p>
         </div>

         <button type="submit">Submit request</button>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#support-form");
     const successMessage = document.querySelector("#success-message");

     const fields = {
       fullName: {
         input: document.querySelector("#full-name"),
         wrapper: document.querySelector("#full-name-field"),
         error: document.querySelector("#full-name-error"),
         validate(value) {
           if (!value.trim()) {
             return "Full name is required.";
           }

           if (value.trim().length < 2) {
             return "Enter your full name.";
           }

           return "";
         }
       },
       email: {
         input: document.querySelector("#email"),
         wrapper: document.querySelector("#email-field"),
         error: document.querySelector("#email-error"),
         validate(value) {
           if (!value.trim()) {
             return "Email address is required.";
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return "Enter a valid email address.";
           }

           return "";
         }
       },
       phone: {
         input: document.querySelector("#phone"),
         wrapper: document.querySelector("#phone-field"),
         error: document.querySelector("#phone-error"),
         validate(value) {
           if (!value.trim()) {
             return "";
           }

           const phonePattern = /^\+?[\d\s().-]{7,20}$/;
           if (!phonePattern.test(value.trim())) {
             return "Enter a valid phone number, such as +1 555 123 4567.";
           }

           return "";
         }
       }
     };

     function setFieldState(field, message) {
       field.error.textContent = message;
       field.wrapper.classList.toggle("invalid", Boolean(message));
       field.input.setAttribute("aria-invalid", String(Boolean(message)));
     }

     function validateField(field) {
       const message = field.validate(field.input.value);
       setFieldState(field, message);
       return !message;
     }

     function validateForm() {
       return Object.values(fields).map(validateField).every(Boolean);
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener("blur", () => validateField(field));
       field.input.addEventListener("input", () => {
         if (field.wrapper.classList.contains("invalid")) {
           validateField(field);
         }

         successMessage.classList.remove("visible");
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       if (!validateForm()) {
         successMessage.classList.remove("visible");
         const firstInvalid = form.querySelector('[aria-invalid="true"]');
         firstInvalid?.focus();
         return;
       }

       form.reset();
       Object.values(fields).forEach((field) => setFieldState(field, ""));
       successMessage.classList.add("visible");
     });
   </script>
 </body>
 </html>

